export const SettlementStatuses = {
  APPROVED: 'APROBADA',
  REJECTED: 'RECHAZADA',
  PENDING_APPROVAL: 'PENDIENTE_APROBACION',
} as const;

export const ClaimStatuses = {
  REGISTERED: 'REGISTRADO',
  SETTLED: 'LIQUIDADO',
  REJECTED: 'RECHAZADO',
  PENDING_REVIEW: 'PENDIENTE_REVISION',
} as const;

export const ReasonCodes = {
  POLICY_NOT_ACTIVE: 'POLIZA_NO_VIGENTE',
  OUT_OF_COVERAGE_PERIOD: 'FUERA_DE_VIGENCIA',
  LATE_REPORT: 'DENUNCIA_EXTEMPORANEA',
  COVERAGE_NOT_CONTRACTED: 'COBERTURA_NO_CONTRATADA',
  WAITING_PERIOD: 'EN_PERIODO_CARENCIA',
  PREMIUM_IN_ARREARS: 'PRIMA_EN_MORA',
  BELOW_DEDUCTIBLE: 'BAJO_DEDUCIBLE',
  INSURED_SUM_EXHAUSTED: 'SUMA_ASEGURADA_AGOTADA',
  FRAUD_SUSPICION: 'SOSPECHA_FRAUDE',
  ABOVE_AUTO_CAP: 'SUPERA_TOPE_AUTOMATICO',
  AUTOMATIC: 'LIQUIDACION_AUTOMATICA',
} as const;

export const ObservationMarks = {
  VIP_ARREARS_TOLERANCE: 'TOLERANCIA_MORA_VIP',
  COVERAGE_LIMIT: 'LIMITE_COBERTURA',
  MINIMUM_DEDUCTIBLE: 'DEDUCIBLE_MINIMO',
  VIP_DISCOUNT: 'DESCUENTO_VIP',
  CLAIMS_PENALTY: 'PENALIZACION_SINIESTRALIDAD',
  INSURED_SUM_CAP: 'TOPE_SUMA_ASEGURADA',
  WITHHOLDING: 'RETENCION_APLICADA',
} as const;

export const ErrorCodes = {
  NOT_REGISTERED: 'ORA-20001',
  PARAMETER_UNDEFINED: 'ORA-20010',
} as const;

export const PolicyVocabulary = {
  ACTIVE: 'VIGENTE',
  LIFE_BRANCH: 'VIDA',
  VIP: 'VIP',
  FIXED_DEDUCTIBLE: 'FIJO',
} as const;

/**
 * Error de negocio devuelto como dato (no es una excepción).
 */
export class BusinessError {
  readonly code: string;
  readonly message: string;

  constructor(code: string, message: string) {
    this.code = code;
    this.message = message;
  }
}

import { Decimal } from '../shared/decimal.ts';

const ISO_DATE = /^([0-9]{4})-([0-9]{2})-([0-9]{2})(?:[T ].*)?$/;

function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function lengthOfMonth(year: number, month: number): number {
  if (month === 2) {
    return isLeapYear(year) ? 29 : 28;
  }
  return [4, 6, 9, 11].includes(month) ? 30 : 31;
}

function isValidCivilDate(year: number, month: number, day: number): boolean {
  return month >= 1 && month <= 12 && day >= 1 && day <= lengthOfMonth(year, month);
}

function toEpochDay(year: number, month: number, day: number): number {
  const adjustedYear = month <= 2 ? year - 1 : year;
  const era = Math.floor(adjustedYear / 400);
  const yearOfEra = adjustedYear - era * 400;
  const shiftedMonth = month > 2 ? month - 3 : month + 9;
  const dayOfYear = Math.floor((153 * shiftedMonth + 2) / 5) + day - 1;
  const dayOfEra =
    yearOfEra * 365 + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100) + dayOfYear;
  return era * 146097 + dayOfEra - 719468;
}

/**
 * Fecha civil sin hora. Las diferencias se expresan en días calendario.
 */
export class LocalDate {
  readonly epochDay: number;

  private constructor(epochDay: number) {
    this.epochDay = epochDay;
  }

  static fromIso(text: string): LocalDate | null {
    const match = ISO_DATE.exec(text.trim());
    if (match === null) {
      return null;
    }
    const year = parseInt(match[1] as string, 10);
    const month = parseInt(match[2] as string, 10);
    const day = parseInt(match[3] as string, 10);
    if (!isValidCivilDate(year, month, day)) {
      return null;
    }
    return new LocalDate(toEpochDay(year, month, day));
  }

  /** Días calendario transcurridos desde `other` hasta esta fecha (puede ser negativo). */
  daysSince(other: LocalDate): Decimal {
    return Decimal.of(this.epochDay - other.epochDay);
  }

  isBefore(other: LocalDate): boolean {
    return this.epochDay < other.epochDay;
  }

  isAfter(other: LocalDate): boolean {
    return this.epochDay > other.epochDay;
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { LocalDate } from './LocalDate.ts';

/**
 * Hechos de entrada de la liquidación, ya tipados.
 */
export interface ClaimFacts {
  readonly claimAmount: Decimal;
  readonly occurrenceDate: LocalDate;
  readonly reportDate: LocalDate;
  readonly coverageCode: string;
  readonly policyStatus: string;
  readonly policyBranch: string;
  readonly policyStartDate: LocalDate;
  readonly policyEndDate: LocalDate;
  readonly sumInsured: Decimal;
  readonly deductibleType: string;
  readonly deductibleValue: Decimal;
  readonly pendingPremium: Decimal;
  readonly customerCategory: string;
  readonly coverageFound: boolean;
  readonly coverageLimit: Decimal;
  readonly coveragePercentage: Decimal;
  readonly waitingDays: Decimal;
  readonly priorLiquidatedClaims365d: Decimal;
  readonly totalIndemnified: Decimal;
}

import type { Decimal } from '../shared/decimal.ts';

/**
 * Parámetros de negocio resueltos (LS_PARAMETROS).
 */
export interface BusinessParameters {
  readonly maxReportDays: Decimal;
  readonly maxReportDaysLife: Decimal;
  readonly vipArrearsTolerance: Decimal;
  readonly minimumDeductible: Decimal;
  readonly vipDeductibleDiscountPct: Decimal;
  readonly maxAnnualClaims: Decimal;
  readonly claimsPenaltyPct: Decimal;
  readonly withholdingThreshold: Decimal;
  readonly withholdingRate: Decimal;
  readonly autoApprovalCap: Decimal;
  readonly fraudAlertDays: Decimal;
  readonly fraudAlertPct: Decimal;
  readonly inflationFactor: Decimal;
}

/**
 * Marcas de observación, inmutables y ordenadas.
 */
export class Observations {
  private readonly marks: readonly string[];

  private constructor(marks: readonly string[]) {
    this.marks = marks;
  }

  static empty(): Observations {
    return new Observations([]);
  }

  /**
   * Agrega una marca al final, respetando el orden de ocurrencia.
   * @rule R-024
   */
  add(mark: string): Observations {
    return new Observations([...this.marks, mark]);
  }

  /**
   * Texto con las marcas separadas por ';'. Vacío si no hay ajustes.
   * @rule R-024
   */
  toText(): string {
    return this.marks.join(';');
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { Observations } from './Observations.ts';

/**
 * Importe intermedio junto con las observaciones acumuladas hasta ese paso.
 */
export class Adjusted {
  readonly amount: Decimal;
  readonly observations: Observations;

  constructor(amount: Decimal, observations: Observations) {
    this.amount = amount;
    this.observations = observations;
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { Observations } from './Observations.ts';
import { ZERO_AMOUNT } from '../services/RoundingPolicy.ts';
import { SettlementStatuses } from './Vocabulary.ts';

export interface SettlementFields {
  readonly status: string;
  readonly reasonCode: string;
  readonly baseAmount: Decimal;
  readonly deductibleAmount: Decimal;
  readonly coveredAmount: Decimal;
  readonly withholdingAmount: Decimal;
  readonly netAmount: Decimal;
  readonly observations: string;
}

/**
 * Resultado de la liquidación (aprobada, pendiente o rechazada).
 */
export class SettlementResult {
  readonly status: string;
  readonly reasonCode: string;
  readonly baseAmount: Decimal;
  readonly deductibleAmount: Decimal;
  readonly coveredAmount: Decimal;
  readonly withholdingAmount: Decimal;
  readonly netAmount: Decimal;
  readonly observations: string;

  constructor(fields: SettlementFields) {
    this.status = fields.status;
    this.reasonCode = fields.reasonCode;
    this.baseAmount = fields.baseAmount;
    this.deductibleAmount = fields.deductibleAmount;
    this.coveredAmount = fields.coveredAmount;
    this.withholdingAmount = fields.withholdingAmount;
    this.netAmount = fields.netAmount;
    this.observations = fields.observations;
  }

  /**
   * Rechazo: todos los importes en cero y se conservan las observaciones acumuladas.
   * @rule R-021
   */
  static rejected(reasonCode: string, observations: Observations): SettlementResult {
    return new SettlementResult({
      status: SettlementStatuses.REJECTED,
      reasonCode,
      baseAmount: ZERO_AMOUNT,
      deductibleAmount: ZERO_AMOUNT,
      coveredAmount: ZERO_AMOUNT,
      withholdingAmount: ZERO_AMOUNT,
      netAmount: ZERO_AMOUNT,
      observations: observations.toText(),
    });
  }
}

import { Decimal } from '../shared/decimal.ts';

export const AMOUNT_SCALE = 2;
export const ZERO: Decimal = Decimal.of(0);
export const ONE_HUNDRED: Decimal = Decimal.of(100);
export const ZERO_AMOUNT: Decimal = Decimal.of(0).setScale(AMOUNT_SCALE, 'HALF_UP');

/**
 * Normaliza un importe a escala 2 con redondeo mitad hacia arriba.
 * @rule R-023
 */
export function toAmount(value: Decimal): Decimal {
  return value.setScale(AMOUNT_SCALE, 'HALF_UP');
}

/**
 * Aplica un porcentaje: ROUND(amount * pct / 100, 2) con HALF_UP.
 * @rule R-023
 */
export function percentOf(amount: Decimal, pct: Decimal): Decimal {
  return amount.times(pct).dividedBy(ONE_HUNDRED, AMOUNT_SCALE, 'HALF_UP');
}

import type { Decimal } from '../shared/decimal.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import { BusinessError } from '../model/BusinessError.ts';
import { ErrorCodes } from '../model/Vocabulary.ts';

export const PARAMETER_CODES = {
  maxReportDays: 'DIAS_MAX_DENUNCIA',
  maxReportDaysLife: 'DIAS_MAX_DENUNCIA_VIDA',
  vipArrearsTolerance: 'TOLERANCIA_MORA_VIP',
  minimumDeductible: 'DEDUCIBLE_MINIMO',
  vipDeductibleDiscountPct: 'PCT_DESCUENTO_DED_VIP',
  maxAnnualClaims: 'MAX_SINIESTROS_ANUAL',
  claimsPenaltyPct: 'PCT_PENALIZACION_SINIEST',
  withholdingThreshold: 'UMBRAL_RETENCION',
  withholdingRate: 'TASA_RETENCION',
  autoApprovalCap: 'TOPE_AUTO_APROBACION',
  fraudAlertDays: 'DIAS_ALERTA_FRAUDE',
  fraudAlertPct: 'PCT_ALERTA_FRAUDE',
  inflationFactor: 'FACTOR_INFLACION',
} as const;

const REQUIRED_CODES: readonly string[] = Object.values(PARAMETER_CODES);

export class ParameterResolution {
  readonly parameters: BusinessParameters | null;
  readonly error: BusinessError | null;

  private constructor(parameters: BusinessParameters | null, error: BusinessError | null) {
    this.parameters = parameters;
    this.error = error;
  }

  static found(parameters: BusinessParameters): ParameterResolution {
    return new ParameterResolution(parameters, null);
  }

  static missing(code: string): ParameterResolution {
    return new ParameterResolution(
      null,
      new BusinessError(ErrorCodes.PARAMETER_UNDEFINED, 'Parametro no definido: ' + code),
    );
  }
}

function build(values: ReadonlyMap<string, Decimal>): BusinessParameters {
  const at = (code: string): Decimal => values.get(code) as Decimal;
  return {
    maxReportDays: at(PARAMETER_CODES.maxReportDays),
    maxReportDaysLife: at(PARAMETER_CODES.maxReportDaysLife),
    vipArrearsTolerance: at(PARAMETER_CODES.vipArrearsTolerance),
    minimumDeductible: at(PARAMETER_CODES.minimumDeductible),
    vipDeductibleDiscountPct: at(PARAMETER_CODES.vipDeductibleDiscountPct),
    maxAnnualClaims: at(PARAMETER_CODES.maxAnnualClaims),
    claimsPenaltyPct: at(PARAMETER_CODES.claimsPenaltyPct),
    withholdingThreshold: at(PARAMETER_CODES.withholdingThreshold),
    withholdingRate: at(PARAMETER_CODES.withholdingRate),
    autoApprovalCap: at(PARAMETER_CODES.autoApprovalCap),
    fraudAlertDays: at(PARAMETER_CODES.fraudAlertDays),
    fraudAlertPct: at(PARAMETER_CODES.fraudAlertPct),
    inflationFactor: at(PARAMETER_CODES.inflationFactor),
  };
}

export class ParameterCatalog {
  /**
   * Exige todos los parámetros consultados (incluido FACTOR_INFLACION, aunque no se use).
   * Si falta alguno, devuelve ORA-20010.
   * @rule R-002
   */
  static resolve(values: ReadonlyMap<string, Decimal>): ParameterResolution {
    for (const code of REQUIRED_CODES) {
      if (!values.has(code)) {
        return ParameterResolution.missing(code);
      }
    }
    return ParameterResolution.found(build(values));
  }
}

import { BusinessError } from '../model/BusinessError.ts';
import { ClaimStatuses, ErrorCodes } from '../model/Vocabulary.ts';

export class ClaimRegistrationGuard {
  /**
   * Solo se liquidan siniestros en estado REGISTRADO. Si el estado no se informa, no se puede verificar.
   * @rule R-001
   */
  static verify(claimId: string | null, claimStatus: string | null): BusinessError | null {
    if (claimStatus === null || claimStatus === ClaimStatuses.REGISTERED) {
      return null;
    }
    const id = claimId === null ? '' : claimId;
    return new BusinessError(
      ErrorCodes.NOT_REGISTERED,
      'El siniestro ' + id + ' no esta en estado REGISTRADO (' + claimStatus + ')',
    );
  }
}

import type { ClaimFacts } from '../../model/ClaimFacts.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';

/**
 * Resultado de una verificación de procedencia: pasa, pasa con marca o rechaza con motivo.
 */
export class CheckOutcome {
  readonly rejectionReason: string | null;
  readonly mark: string | null;

  private constructor(rejectionReason: string | null, mark: string | null) {
    this.rejectionReason = rejectionReason;
    this.mark = mark;
  }

  static pass(): CheckOutcome {
    return new CheckOutcome(null, null);
  }

  static passWithMark(mark: string): CheckOutcome {
    return new CheckOutcome(null, mark);
  }

  static reject(reason: string): CheckOutcome {
    return new CheckOutcome(reason, null);
  }
}

export interface EligibilityCheck {
  evaluate(claim: ClaimFacts, params: BusinessParameters): CheckOutcome;
}

import type { ClaimFacts } from '../../model/ClaimFacts.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import { CheckOutcome } from './EligibilityCheck.ts';
import type { EligibilityCheck } from './EligibilityCheck.ts';
import { ObservationMarks, PolicyVocabulary, ReasonCodes } from '../../model/Vocabulary.ts';
import { ZERO } from '../../services/RoundingPolicy.ts';

export class PolicyActiveCheck implements EligibilityCheck {
  /**
   * Solo se indemnizan pólizas en estado VIGENTE.
   * @rule R-004
   */
  evaluate(claim: ClaimFacts, _params: BusinessParameters): CheckOutcome {
    if (claim.policyStatus !== PolicyVocabulary.ACTIVE) {
      return CheckOutcome.reject(ReasonCodes.POLICY_NOT_ACTIVE);
    }
    return CheckOutcome.pass();
  }
}

export class PolicyPeriodCheck implements EligibilityCheck {
  /**
   * La ocurrencia debe estar en [inicio, fin] de la póliza, ambos incluidos.
   * @rule R-005
   */
  evaluate(claim: ClaimFacts, _params: BusinessParameters): CheckOutcome {
    const before = claim.occurrenceDate.isBefore(claim.policyStartDate);
    const after = claim.occurrenceDate.isAfter(claim.policyEndDate);
    if (before || after) {
      return CheckOutcome.reject(ReasonCodes.OUT_OF_COVERAGE_PERIOD);
    }
    return CheckOutcome.pass();
  }
}

export class ReportDeadlineCheck implements EligibilityCheck {
  /**
   * Plazo máximo de denuncia: VIDA usa DIAS_MAX_DENUNCIA_VIDA, el resto DIAS_MAX_DENUNCIA. El último día es válido.
   * @rule R-006
   */
  evaluate(claim: ClaimFacts, params: BusinessParameters): CheckOutcome {
    const days = claim.reportDate.daysSince(claim.occurrenceDate);
    const isLife = claim.policyBranch === PolicyVocabulary.LIFE_BRANCH;
    const limit = isLife ? params.maxReportDaysLife : params.maxReportDays;
    if (days.gt(limit)) {
      return CheckOutcome.reject(ReasonCodes.LATE_REPORT);
    }
    return CheckOutcome.pass();
  }
}

export class CoverageContractedCheck implements EligibilityCheck {
  /**
   * La cobertura reclamada debe estar contratada en la póliza.
   * @rule R-007
   */
  evaluate(claim: ClaimFacts, _params: BusinessParameters): CheckOutcome {
    if (!claim.coverageFound) {
      return CheckOutcome.reject(ReasonCodes.COVERAGE_NOT_CONTRACTED);
    }
    return CheckOutcome.pass();
  }
}

export class WaitingPeriodCheck implements EligibilityCheck {
  /**
   * Deben haber transcurrido al menos los días de carencia desde el inicio de la póliza.
   * @rule R-008
   */
  evaluate(claim: ClaimFacts, _params: BusinessParameters): CheckOutcome {
    const daysSinceStart = claim.occurrenceDate.daysSince(claim.policyStartDate);
    if (daysSinceStart.lt(claim.waitingDays)) {
      return CheckOutcome.reject(ReasonCodes.WAITING_PERIOD);
    }
    return CheckOutcome.pass();
  }
}

export class PremiumArrearsCheck implements EligibilityCheck {
  /**
   * Prima pendiente: rechaza, salvo VIP con deuda <= tolerancia, que continúa con marca.
   * @rule R-009
   */
  evaluate(claim: ClaimFacts, params: BusinessParameters): CheckOutcome {
    if (!claim.pendingPremium.gt(ZERO)) {
      return CheckOutcome.pass();
    }
    if (this.isVipWithinTolerance(claim, params)) {
      return CheckOutcome.passWithMark(ObservationMarks.VIP_ARREARS_TOLERANCE);
    }
    return CheckOutcome.reject(ReasonCodes.PREMIUM_IN_ARREARS);
  }

  /**
   * @rule R-009
   */
  private isVipWithinTolerance(claim: ClaimFacts, params: BusinessParameters): boolean {
    const isVip = claim.customerCategory === PolicyVocabulary.VIP;
    return isVip && claim.pendingPremium.lte(params.vipArrearsTolerance);
  }
}

import type { ClaimFacts } from '../../model/ClaimFacts.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import { Observations } from '../../model/Observations.ts';
import type { EligibilityCheck } from './EligibilityCheck.ts';
import {
  CoverageContractedCheck,
  PolicyActiveCheck,
  PolicyPeriodCheck,
  PremiumArrearsCheck,
  ReportDeadlineCheck,
  WaitingPeriodCheck,
} from './EligibilityChecks.ts';

export class EligibilityResult {
  readonly rejectionReason: string | null;
  readonly observations: Observations;

  private constructor(rejectionReason: string | null, observations: Observations) {
    this.rejectionReason = rejectionReason;
    this.observations = observations;
  }

  static accepted(observations: Observations): EligibilityResult {
    return new EligibilityResult(null, observations);
  }

  static rejected(reason: string): EligibilityResult {
    return new EligibilityResult(reason, Observations.empty());
  }
}

function defaultChecks(): readonly EligibilityCheck[] {
  return [
    new PolicyActiveCheck(),
    new PolicyPeriodCheck(),
    new ReportDeadlineCheck(),
    new CoverageContractedCheck(),
    new WaitingPeriodCheck(),
    new PremiumArrearsCheck(),
  ];
}

export class EligibilityChain {
  private readonly checks: readonly EligibilityCheck[];

  constructor(checks?: readonly EligibilityCheck[]) {
    this.checks = checks === undefined ? defaultChecks() : checks;
  }

  /**
   * Orden fijo: póliza, vigencia, plazo de denuncia, cobertura, carencia y morosidad.
   * La primera que falla determina el rechazo y las siguientes no se evalúan.
   * @rule R-003
   */
  evaluate(claim: ClaimFacts, params: BusinessParameters): EligibilityResult {
    let observations = Observations.empty();
    for (const check of this.checks) {
      const outcome = check.evaluate(claim, params);
      if (outcome.rejectionReason !== null) {
        return EligibilityResult.rejected(outcome.rejectionReason);
      }
      if (outcome.mark !== null) {
        observations = observations.add(outcome.mark);
      }
    }
    return EligibilityResult.accepted(observations);
  }
}

import type { ClaimFacts } from '../../model/ClaimFacts.ts';
import type { Observations } from '../../model/Observations.ts';
import { Adjusted } from '../../model/Adjusted.ts';
import { ObservationMarks } from '../../model/Vocabulary.ts';
import { toAmount } from '../../services/RoundingPolicy.ts';

export class BaseAmountPolicy {
  /**
   * Base = lo reclamado sin superar el límite de cobertura; marca LIMITE_COBERTURA si se topa.
   * @rule R-010
   */
  apply(claim: ClaimFacts, observations: Observations): Adjusted {
    if (claim.claimAmount.gt(claim.coverageLimit)) {
      return new Adjusted(
        toAmount(claim.coverageLimit),
        observations.add(ObservationMarks.COVERAGE_LIMIT),
      );
    }
    return new Adjusted(toAmount(claim.claimAmount), observations);
  }
}

import type { Decimal } from '../../shared/decimal.ts';
import type { ClaimFacts } from '../../model/ClaimFacts.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import type { Observations } from '../../model/Observations.ts';
import { Adjusted } from '../../model/Adjusted.ts';
import { ObservationMarks, PolicyVocabulary } from '../../model/Vocabulary.ts';
import { percentOf, toAmount } from '../../services/RoundingPolicy.ts';

export interface DeductibleStrategy {
  calculate(
    claim: ClaimFacts,
    params: BusinessParameters,
    base: Decimal,
    observations: Observations,
  ): Adjusted;
}

export class FixedDeductibleStrategy implements DeductibleStrategy {
  /**
   * Deducible FIJO: el monto pactado, sin mínimo.
   * @rule R-011
   */
  calculate(
    claim: ClaimFacts,
    _params: BusinessParameters,
    _base: Decimal,
    observations: Observations,
  ): Adjusted {
    return new Adjusted(toAmount(claim.deductibleValue), observations);
  }
}

export class PercentageDeductibleStrategy implements DeductibleStrategy {
  /**
   * Deducible PORCENTAJE sobre el monto base (HALF_UP, 2 decimales), con mínimo DEDUCIBLE_MINIMO.
   * @rule R-011
   * @rule R-023
   */
  calculate(
    claim: ClaimFacts,
    params: BusinessParameters,
    base: Decimal,
    observations: Observations,
  ): Adjusted {
    const computed = percentOf(base, claim.deductibleValue);
    if (computed.lt(params.minimumDeductible)) {
      return new Adjusted(
        toAmount(params.minimumDeductible),
        observations.add(ObservationMarks.MINIMUM_DEDUCTIBLE),
      );
    }
    return new Adjusted(computed, observations);
  }
}

export class DeductibleCalculator {
  private readonly fixed: DeductibleStrategy;
  private readonly percentage: DeductibleStrategy;

  constructor() {
    this.fixed = new FixedDeductibleStrategy();
    this.percentage = new PercentageDeductibleStrategy();
  }

  /**
   * FIJO usa la estrategia fija; cualquier otro tipo se trata como PORCENTAJE.
   * @rule R-011
   */
  calculate(claim: ClaimFacts, params: BusinessParameters, base: Adjusted): Adjusted {
    const strategy =
      claim.deductibleType === PolicyVocabulary.FIXED_DEDUCTIBLE ? this.fixed : this.percentage;
    return strategy.calculate(claim, params, base.amount, base.observations);
  }
}

import type { ClaimFacts } from '../../model/ClaimFacts.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import { Adjusted } from '../../model/Adjusted.ts';
import { ObservationMarks, PolicyVocabulary } from '../../model/Vocabulary.ts';
import { ONE_HUNDRED, ZERO, percentOf } from '../../services/RoundingPolicy.ts';

export class VipDeductibleDiscount {
  /**
   * Clientes VIP pagan (100 - PCT_DESCUENTO_DED_VIP)% del deducible ya calculado, si es mayor que cero.
   * @rule R-012
   * @rule R-023
   */
  apply(claim: ClaimFacts, params: BusinessParameters, deductible: Adjusted): Adjusted {
    const isVip = claim.customerCategory === PolicyVocabulary.VIP;
    if (!isVip || !deductible.amount.gt(ZERO)) {
      return deductible;
    }
    const payableFactor = ONE_HUNDRED.minus(params.vipDeductibleDiscountPct);
    return new Adjusted(
      percentOf(deductible.amount, payableFactor),
      deductible.observations.add(ObservationMarks.VIP_DISCOUNT),
    );
  }
}

import type { Decimal } from '../../shared/decimal.ts';
import { ZERO, percentOf } from '../../services/RoundingPolicy.ts';

export class CoveredAmountCalculator {
  /**
   * covered = ROUND((base - deducible) * porcentaje_cobertura / 100, 2), HALF_UP.
   * @rule R-013
   * @rule R-023
   */
  calculate(base: Decimal, deductible: Decimal, coveragePercentage: Decimal): Decimal {
    return percentOf(base.minus(deductible), coveragePercentage);
  }

  /**
   * Un monto cubierto <= 0 queda bajo el deducible y se rechaza.
   * @rule R-013
   */
  isBelowDeductible(covered: Decimal): boolean {
    return covered.lte(ZERO);
  }
}

import type { ClaimFacts } from '../../model/ClaimFacts.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
import { Adjusted } from '../../model/Adjusted.ts';
import { ObservationMarks } from '../../model/Vocabulary.ts';
import { ONE_HUNDRED, percentOf } from '../../services/RoundingPolicy.ts';

export class ClaimsFrequencyPenalty {
  /**
   * Con MAX_SINIESTROS_ANUAL o más siniestros liquidados previos en 365 días,
   * el cubierto se reduce en PCT_PENALIZACION_SINIEST%.
   * @rule R-014
   * @rule R-023
   */
  apply(claim: ClaimFacts, params: BusinessParameters, covered: Adjusted): Adjusted {
    if (claim.priorLiquidatedClaims365d.lt(params.maxAnnualClaims)) {
      return covered;
    }
    const payableFactor = ONE_HUNDRED.minus(params.claimsPenaltyPct);
    return new Adjusted(
      percentOf(covered.amount, payableFactor),
      covered.observations.add(ObservationMarks.CLAIMS_PENALTY),
    );
  }
}

import type { Decimal } from '../../shared/decimal.ts';
import type { ClaimFacts } from '../../model/ClaimFacts.ts';
import { Adjusted } from '../../model/Adjusted.ts';
import { ObservationMarks } from '../../model/Vocabulary.ts';
import { ZERO, toAmount } from '../../services/RoundingPolicy.ts';

export class InsuredSumCap {
  /**
   * Suma remanente = suma asegurada - total indemnificado.
   * @rule R-015
   * @rule R-016
   */
  remaining(claim: ClaimFacts): Decimal {
    return toAmount(claim.sumInsured.minus(claim.totalIndemnified));
  }

  /**
   * Sin saldo disponible (remanente <= 0) el siniestro se rechaza.
   * @rule R-015
   */
  isExhausted(claim: ClaimFacts): boolean {
    return this.remaining(claim).lte(ZERO);
  }

  /**
   * Si el cubierto supera el remanente se paga el remanente y se marca TOPE_SUMA_ASEGURADA.
   * @rule R-016
   */
  apply(claim: ClaimFacts, covered: Adjusted): Adjusted {
    const remaining = this.remaining(claim);
    if (covered.amount.gt(remaining)) {
      return new Adjusted(remaining, covered.observations.add(ObservationMarks.INSURED_SUM_CAP));
    }
    return covered;
  }
}

