export class WithholdingPolicy {
  /**
   * Ramos distintos de VIDA con cubierto > UMBRAL_RETENCION (estricto): retención TASA_RETENCION%.
   * Devuelve la retención y las observaciones acumuladas.
   * @rule R-017
   * @rule R-023
   */
  calculate(claim: ClaimFacts, params: BusinessParameters, covered: Adjusted): Adjusted {
    if (!this.applies(claim, params, covered.amount)) {
      return new Adjusted(ZERO_AMOUNT, covered.observations);
    }
    return new Adjusted(
      percentOf(covered.amount, params.withholdingRate),
      covered.observations.add(ObservationMarks.WITHHOLDING),
    );
  }

  /**
   * @rule R-017
   */
  private applies(claim: ClaimFacts, params: BusinessParameters, covered: Decimal): boolean {
    const isLife = claim.policyBranch === PolicyVocabulary.LIFE_BRANCH;
    return !isLife && covered.gt(params.withholdingThreshold);
  }
}

import type { Decimal } from '../../shared/decimal.ts';

export class NetAmountCalculator {
  /**
   * Neto a pagar = monto cubierto - retención.
   * @rule R-018
   */
  calculate(covered: Decimal, withholding: Decimal): Decimal {
    return covered.minus(withholding);
  }
}

import type { ClaimFacts } from '../../model/ClaimFacts.ts';
import type { BusinessParameters } from '../../model/BusinessParameters.ts';
