export class FraudAlertSpecification {
  /**
   * Fraude: ocurre dentro de los primeros DIAS_ALERTA_FRAUDE días de la póliza (inclusive) y
   * lo reclamado (no la base topada) es >= ROUND(limite * PCT_ALERTA_FRAUDE / 100, 2).
   * @rule R-019
   * @rule R-023
   */
  isSatisfiedBy(claim: ClaimFacts, params: BusinessParameters): boolean {
    const daysSinceStart = claim.occurrenceDate.daysSince(claim.policyStartDate);
    if (daysSinceStart.gt(params.fraudAlertDays)) {
      return false;
    }
    const threshold = percentOf(claim.coverageLimit, params.fraudAlertPct);
    return claim.claimAmount.gte(threshold);
  }
}

