export class FinalDecision {
  readonly status: string;
  readonly reasonCode: string;

  constructor(status: string, reasonCode: string) {
    this.status = status;
    this.reasonCode = reasonCode;
  }
}

export class FinalStatusPolicy {
  /**
   * La sospecha de fraude tiene prioridad; luego neto > TOPE_AUTO_APROBACION (estricto) queda
   * pendiente; en otro caso se aprueba automáticamente.
   * @rule R-020
   * @rule R-019
   */
  decide(fraudSuspected: boolean, net: Decimal, params: BusinessParameters): FinalDecision {
    if (fraudSuspected) {
      return new FinalDecision(SettlementStatuses.PENDING_APPROVAL, ReasonCodes.FRAUD_SUSPICION);
    }
    if (net.gt(params.autoApprovalCap)) {
      return new FinalDecision(SettlementStatuses.PENDING_APPROVAL, ReasonCodes.ABOVE_AUTO_CAP);
    }
    return new FinalDecision(SettlementStatuses.APPROVED, ReasonCodes.AUTOMATIC);
  }
}

import { ClaimStatuses, SettlementStatuses } from '../../model/Vocabulary.ts';

export class ClaimStatusMapper {
  /**
   * APROBADA a LIQUIDADO, RECHAZADA a RECHAZADO, PENDIENTE_APROBACION a PENDIENTE_REVISION.
   * @rule R-022
   */
  toClaimStatus(settlementStatus: string): string {
    if (settlementStatus === SettlementStatuses.APPROVED) {
      return ClaimStatuses.SETTLED;
    }
    if (settlementStatus === SettlementStatuses.REJECTED) {
      return ClaimStatuses.REJECTED;
    }
    return ClaimStatuses.PENDING_REVIEW;
  }
}

