export interface BatchCandidate {
  readonly claimId: string;
  readonly claimStatus: string;
  readonly reportDate: LocalDate;
}

export class BatchSelectionSpecification {
  /**
   * Candidato: estado REGISTRADO y denuncia igual o anterior a la fecha de proceso.
   * @rule R-025
   */
  isSatisfiedBy(candidate: BatchCandidate, processDate: LocalDate): boolean {
    const registered = candidate.claimStatus === ClaimStatuses.REGISTERED;
    return registered && !candidate.reportDate.isAfter(processDate);
  }

  /**
   * Selecciona y ordena de forma ascendente por identificador (el orden afecta a siniestros posteriores).
   * Se asume identificador numérico.
   * @rule R-025
   */
  select(candidates: readonly BatchCandidate[], processDate: LocalDate): readonly BatchCandidate[] {
    return candidates
      .filter((candidate) => this.isSatisfiedBy(candidate, processDate))
      .sort((a, b) => Decimal.of(a.claimId).compareTo(Decimal.of(b.claimId)));
  }
}

import { Decimal } from '../../shared/decimal.ts';
import type { SettlementResult } from '../../model/SettlementResult.ts';
import { SettlementStatuses } from '../../model/Vocabulary.ts';
import { ZERO_AMOUNT } from '../../services/RoundingPolicy.ts';

export interface BatchCounters {
  readonly settled: number;
  readonly rejected: number;
  readonly pending: number;
  readonly errors: number;
}

/**
 * Resumen del lote: contadores por estado y total neto aprobado.
 */
export class BatchTotals {
  readonly counters: BatchCounters;
  readonly totalNetApproved: Decimal;

  constructor(counters: BatchCounters, totalNetApproved: Decimal) {
    this.counters = counters;
    this.totalNetApproved = totalNetApproved;
  }

  static empty(): BatchTotals {
    return new BatchTotals({ settled: 0, rejected: 0, pending: 0, errors: 0 }, ZERO_AMOUNT);
  }

  /**
   * Solo las liquidaciones APROBADAS (siniestro LIQUIDADO) suman al total neto.
   * @rule R-026
   */
  register(result: SettlementResult): BatchTotals {
    const c = this.counters;
    if (result.status === SettlementStatuses.APPROVED) {
      const next = { ...c, settled: c.settled + 1 };
      return new BatchTotals(next, this.totalNetApproved.plus(result.netAmount));
    }
    if (result.status === SettlementStatuses.REJECTED) {
      return new BatchTotals({ ...c, rejected: c.rejected + 1 }, this.totalNetApproved);
    }
    return new BatchTotals({ ...c, pending: c.pending + 1 }, this.totalNetApproved);
  }

  /**
   * Un siniestro con error se cuenta aparte y el lote continúa.
   * @rule R-026
   */
  registerError(): BatchTotals {
    const c = this.counters;
    return new BatchTotals({ ...c, errors: c.errors + 1 }, this.totalNetApproved);
  }
}

