import { CoveredAmountCalculator } from '../rules/calculation/CoveredAmountCalculator.ts';
import { ClaimsFrequencyPenalty } from '../rules/calculation/ClaimsFrequencyPenalty.ts';
import { InsuredSumCap } from '../rules/calculation/InsuredSumCap.ts';
