import { NetAmountCalculator } from '../rules/calculation/NetAmountCalculator.ts';
import { FraudAlertSpecification } from '../rules/decision/FraudAlertSpecification.ts';
import { FinalStatusPolicy } from '../rules/decision/FinalStatusPolicy.ts';
import { toAmount } from './RoundingPolicy.ts';

/**
 * Servicio de dominio que orquesta el pipeline de reglas de liquidación.
 */
export class ClaimSettlementService {
  private readonly eligibility = new EligibilityChain();
  private readonly basePolicy = new BaseAmountPolicy();
  private readonly deductibles = new DeductibleCalculator();
  private readonly vipDiscount = new VipDeductibleDiscount();
  private readonly coveredCalculator = new CoveredAmountCalculator();
  private readonly penalty = new ClaimsFrequencyPenalty();
  private readonly sumCap = new InsuredSumCap();
  private readonly withholdingPolicy = new WithholdingPolicy();
  private readonly netCalculator = new NetAmountCalculator();
  private readonly fraud = new FraudAlertSpecification();
  private readonly finalStatus = new FinalStatusPolicy();

  /**
   * Ejecuta las reglas en el orden del legacy. Los rechazos devuelven importes en cero.
   * @rule R-003
   * @rule R-021
   */
  settle(claim: ClaimFacts, params: BusinessParameters): SettlementResult {
    const eligibility = this.eligibility.evaluate(claim, params);
    if (eligibility.rejectionReason !== null) {
      return SettlementResult.rejected(eligibility.rejectionReason, Observations.empty());
    }
    const base = this.basePolicy.apply(claim, eligibility.observations);
    const deductible = this.vipDiscount.apply(
      claim,
      params,
      this.deductibles.calculate(claim, params, base),
    );
    return this.settleCovered(claim, params, base, deductible);
  }

  /**
   * @rule R-013
   * @rule R-014
   * @rule R-015
   * @rule R-016
   */
  private settleCovered(
    claim: ClaimFacts,
    params: BusinessParameters,
    base: Adjusted,
    deductible: Adjusted,
  ): SettlementResult {
    const covered = this.coveredCalculator.calculate(
      base.amount,
      deductible.amount,
      claim.coveragePercentage,
    );
    if (this.coveredCalculator.isBelowDeductible(covered)) {
      return SettlementResult.rejected(ReasonCodes.BELOW_DEDUCTIBLE, deductible.observations);
    }
    const penalized = this.penalty.apply(claim, params, new Adjusted(covered, deductible.observations));
    if (this.sumCap.isExhausted(claim)) {
      return SettlementResult.rejected(ReasonCodes.INSURED_SUM_EXHAUSTED, penalized.observations);
    }
    const capped = this.sumCap.apply(claim, penalized);
    return this.finish(claim, params, base.amount, deductible.amount, capped);
  }

  /**
   * @rule R-017
   * @rule R-018
   * @rule R-019
   * @rule R-020
   */
  private finish(
    claim: ClaimFacts,
    params: BusinessParameters,
    base: Adjusted['amount'],
    deductible: Adjusted['amount'],
    covered: Adjusted,
  ): SettlementResult {
    const withholding = this.withholdingPolicy.calculate(claim, params, covered);
    const net = this.netCalculator.calculate(covered.amount, withholding.amount);
    const decision = this.finalStatus.decide(this.fraud.isSatisfiedBy(claim, params), net, params);
    return new SettlementResult({
      status: decision.status,
      reasonCode: decision.reasonCode,
      baseAmount: toAmount(base),
      deductibleAmount: toAmount(deductible),
      coveredAmount: toAmount(covered.amount),
      withholdingAmount: toAmount(withholding.amount),
      netAmount: toAmount(net),
      observations: withholding.observations.toText(),
    });
  }
}

