/**
 * Caso de uso: liquidar un siniestro. Los errores de negocio se devuelven como resultado.
 */
export class SettleClaimUseCase {
  private readonly audit: SettlementAuditPort;
  private readonly service: ClaimSettlementService;
  private readonly statusMapper: ClaimStatusMapper;

  constructor(audit: SettlementAuditPort) {
    this.audit = audit;
    this.service = new ClaimSettlementService();
    this.statusMapper = new ClaimStatusMapper();
  }

  execute(command: SettleClaimCommand): SettleClaimOutcome {
    const stateError = ClaimRegistrationGuard.verify(command.claimId, command.claimStatus);
    if (stateError !== null) {
      return SettleClaimOutcome.failed(stateError);
    }
    const resolution = ParameterCatalog.resolve(command.parameters);
    if (resolution.parameters === null || resolution.error !== null) {
      return SettleClaimOutcome.failed(resolution.error as NonNullable<typeof resolution.error>);
    }
    const settlement = this.service.settle(command.facts, resolution.parameters);
    this.recordAudit(command.claimId, settlement);
    return SettleClaimOutcome.settled(settlement);
  }

  private recordAudit(claimId: string | null, settlement: SettlementResult): void {
    this.audit.record({
      claimId,
      settlementStatus: settlement.status,
      reasonCode: settlement.reasonCode,
      newClaimStatus: this.statusMapper.toClaimStatus(settlement.status),
      netAmount: settlement.netAmount.toString(),
    });
  }
}

