import { Decimal } from '../../domain/shared/decimal.ts';
import { LocalDate } from '../../domain/model/LocalDate.ts';

const DECIMAL_PATTERN = /^-?[0-9]+(\.[0-9]+)?$/;
const INTEGER_PATTERN = /^[0-9]+$/;
const TRUE_VALUES: readonly string[] = ['true', '1', 's', 'si', 'y', 'yes'];
const FALSE_VALUES: readonly string[] = ['false', '0', 'n', 'no'];

export class InvalidInputError extends Error {
  readonly field: string;

  constructor(field: string, message: string) {
    super(message);
    this.field = field;
  }
}

/**
 * Lee campos de la entrada (todo cadenas) y los convierte a tipos del dominio.
 */
export class InputFieldReader {
  private readonly input: Record<string, string>;

  constructor(input: Record<string, string>) {
    this.input = input;
  }

  optionalText(name: string): string | null {
    const raw = this.input[name];
    if (raw === undefined || raw === null) {
      return null;
    }
    const trimmed = String(raw).trim();
    return trimmed === '' ? null : trimmed;
  }

  text(name: string): string {
    const value = this.optionalText(name);
    if (value === null) {
      throw new InvalidInputError(name, 'campo requerido');
    }
    return value;
  }

  decimal(name: string, scale: number): Decimal {
    const value = this.text(name);
    if (!DECIMAL_PATTERN.test(value)) {
      throw new InvalidInputError(name, 'decimal invalido');
    }
    return Decimal.of(value).setScale(scale, 'HALF_UP');
  }

  integer(name: string): Decimal {
    const value = this.text(name);
    if (!INTEGER_PATTERN.test(value)) {
      throw new InvalidInputError(name, 'entero invalido');
    }
    return Decimal.of(value);
  }

  date(name: string): LocalDate {
    const parsed = LocalDate.fromIso(this.text(name));
    if (parsed === null) {
      throw new InvalidInputError(name, 'fecha invalida (se espera YYYY-MM-DD)');
    }
    return parsed;
  }

  boolean(name: string): boolean {
    const value = this.text(name).toLowerCase();
    if (TRUE_VALUES.includes(value)) {
      return true;
    }
    if (FALSE_VALUES.includes(value)) {
      return false;
    }
    throw new InvalidInputError(name, 'booleano invalido');
  }

  rawText(name: string): string {
    const raw = this.input[name];
    return raw === undefined || raw === null ? '' : String(raw);
  }
}

import { Decimal } from '../../domain/shared/decimal.ts';
import { InvalidInputError } from './InputFieldReader.ts';

const SEPARATORS = /[;,|\n\r]+/;
const ENTRY = /^([A-Za-z_][A-Za-z0-9_]*)[=:](-?[0-9]+(\.[0-9]+)?)$/;
const PARAMETER_SCALE = 4;

/**
 * Convierte el texto de business_parameters (CODIGO=valor, separados por ; , | o salto de línea)
 * en un mapa código a Decimal de escala 4 (NUMBER(14,4)).
 */
export class ParameterListParser {
  static parse(raw: string): ReadonlyMap<string, Decimal> {
    const values = new Map<string, Decimal>();
    for (const entry of raw.split(SEPARATORS)) {
      ParameterListParser.addEntry(values, entry.trim());
    }
    return values;
  }

  private static addEntry(values: Map<string, Decimal>, entry: string): void {
    if (entry === '') {
      return;
    }
    const match = ENTRY.exec(entry);
    if (match === null) {
      throw new InvalidInputError('business_parameters', 'entrada de parametro invalida');
    }
    const code = (match[1] as string).toUpperCase();
    values.set(code, Decimal.of(match[2] as string).setScale(PARAMETER_SCALE, 'HALF_UP'));
  }
}

import type { ClaimFacts } from '../../domain/model/ClaimFacts.ts';
import type { SettleClaimCommand } from '../../application/SettleClaimCommand.ts';
import { InputFieldReader, InvalidInputError } from './InputFieldReader.ts';
import { ParameterListParser } from './ParameterListParser.ts';

export class MappingResult {
  readonly command: SettleClaimCommand | null;
  readonly errorMessage: string | null;

  constructor(command: SettleClaimCommand | null, errorMessage: string | null) {
    this.command = command;
    this.errorMessage = errorMessage;
  }
}

function readFacts(reader: InputFieldReader): ClaimFacts {
  return {
    claimAmount: reader.decimal('claim_amount', 2),
    occurrenceDate: reader.date('occurrence_date'),
    reportDate: reader.date('report_date'),
    coverageCode: reader.text('coverage_code'),
    policyStatus: reader.text('policy_status'),
    policyBranch: reader.text('policy_branch'),
    policyStartDate: reader.date('policy_start_date'),
    policyEndDate: reader.date('policy_end_date'),
    sumInsured: reader.decimal('sum_insured', 2),
    deductibleType: reader.text('deductible_type'),
    deductibleValue: reader.decimal('deductible_value', 2),
    pendingPremium: reader.decimal('pending_premium', 2),
    customerCategory: reader.text('customer_category'),
    coverageFound: reader.boolean('coverage_found'),
    coverageLimit: reader.decimal('coverage_limit', 2),
    coveragePercentage: reader.decimal('coverage_percentage', 2),
    waitingDays: reader.integer('waiting_days'),
    priorLiquidatedClaims365d: reader.integer('prior_liquidated_claims_365d'),
    totalIndemnified: reader.decimal('total_indemnified', 2),
  };
}

/**
 * Adaptador de entrada: traduce el mapa de cadenas al comando tipado del caso de uso.
 */
export class ClaimInputMapper {
  static map(input: Record<string, string>): MappingResult {
    try {
      const reader = new InputFieldReader(input);
      const command: SettleClaimCommand = {
        claimId: reader.optionalText('claim_id'),
        claimStatus: reader.optionalText('claim_status'),
        facts: readFacts(reader),
        parameters: ParameterListParser.parse(reader.rawText('business_parameters')),
      };
      return new MappingResult(command, null);
    } catch (error) {
      if (error instanceof InvalidInputError) {
        return new MappingResult(null, error.field + ': ' + error.message);
      }
      throw error;
    }
  }
}

