}

function errorRecord(errorCode: string): Record<string, string> {
  const zero = zeroAmountText();
  return {
    status: '',
    reason_code: '',
    base_amount: zero,
    deductible_amount: zero,
    covered_amount: zero,
    withholding_amount: zero,
    net_amount: zero,
    observations: '',
    error_code: errorCode,
  };
}

function settlementRecord(result: SettlementResult): Record<string, string> {
  return {
    status: result.status,
    reason_code: result.reasonCode,
    base_amount: result.baseAmount.toString(),
    deductible_amount: result.deductibleAmount.toString(),
    covered_amount: result.coveredAmount.toString(),
    withholding_amount: result.withholdingAmount.toString(),
    net_amount: result.netAmount.toString(),
    observations: result.observations,
    error_code: '',
  };
}

/**
 * Serializa el resultado del caso de uso a un mapa de cadenas.
 */
export class SettlementResponseMapper {
  static toRecord(outcome: SettleClaimOutcome): Record<string, string> {
    if (outcome.error !== null) {
      return errorRecord(outcome.error.code);
    }
    return settlementRecord(outcome.settlement as SettlementResult);
  }

  static invalidInput(): Record<string, string> {
    return errorRecord(INVALID_INPUT_CODE);
  }
}

import { SettleClaimUseCase } from './application/SettleClaimUseCase.ts';
import { InMemorySettlementAudit } from './infrastructure/audit/InMemorySettlementAudit.ts';
import { ClaimInputMapper } from './infrastructure/input/ClaimInputMapper.ts';
import { SettlementResponseMapper } from './infrastructure/output/SettlementResponseMapper.ts';

/**
 * Punto de entrada: compone dependencias y delega al caso de uso. No contiene lógica de negocio.
 */
export function execute(input: Record<string, string>): Record<string, string> {
  const mapping = ClaimInputMapper.map(input);
  if (mapping.command === null) {
    return SettlementResponseMapper.invalidInput();
  }
  const useCase = new SettleClaimUseCase(new InMemorySettlementAudit());
  return SettlementResponseMapper.toRecord(useCase.execute(mapping.command));
}

